import sys

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    n = int(data)
    s = str(n)
    sq = n * n
    if str(sq).endswith(s):
        print("Automorphic Number")
    else:
        print("Not an Automorphic Number")

if __name__ == "__main__":
    main()
